import {APP_VERSION,LIMITS,CATEGORIES,UNITS,STATES,COMPONENTS,blankRecipe,id,withRecipe,validateNotebook,searchRecipes,scaledQuantity,displayQuantity,exclusions} from './domain.js?v=0.6.4';
import {NotebookStore,friendlyStorageError} from './storage.js?v=0.6.4';
import {makeBackup,readBackup,prepareMerge} from './backup.js?v=0.6.4';
import {preparePhoto,verifyPhotoDecoding} from './photos.js?v=0.6.4';
import {installCatalogue, installAdditionalCatalogues, catalogueCount, ingredientGroups, methodText, hasOriginalMethod, culinaryMethod, ingredientPreparation} from './catalogue.js?v=0.6.4';
import {startOffline,offlineMessage} from './offline.js?v=0.6.4';
import {dayString,monday,shiftDay,remaining,timerAction,beginCooking,setMenu,rebuildShopping,harvestToReserve} from './workflows.js?v=0.6.4';
import {esc,art,artwork,banner,flowers,coverDecor,frame,heading,section,action,tools} from './visual.js?v=0.6.4';
import {capturePageTurn,playPageTurn} from './page-turn.js?v=0.6.4';
import {retroTimer,wireTimerDial,updateTimerDial} from './retro-timer.js?v=0.6.4';
import {installGardenPantry,installMetricPantry,addPantryLot,openPantryJar,useReserve,undoReserveUse} from './garden-pantry.js?v=0.6.4';
import {GARDEN_GUIDES} from './garden-pantry-data.js?v=0.6.4';
import {plantAdvice,gardenGuideCards,recipeLinks,procedureBody,lotForm,lotSummary,reserveBody} from './garden-pantry-ui.js?v=0.6.4';
import {metricPreparation,metricQuantity,fromMetricQuantity,metricText} from './metric.js?v=0.6.4';
const main=document.querySelector('#app'),message=document.querySelector('#message'),store=new NotebookStore();
let offlineState='preparing';
function showOffline(state){offlineState=state;const node=document.querySelector('#offline-status');if(node)node.textContent=offlineMessage(state);}
let book,draft,dirty=false,busy=false,photoFile,removePhoto=false,stagedBackup,urls=[],lastRoute='#accueil',week=monday(),category='',searchQuery='',plantSpace='Pot',audioContext,wakeLock,expiredKey='';
const servingsById=new Map();
const options=(values,selected)=>values.map(value=>`<option${value===selected?' selected':''}>${esc(value)}</option>`).join('');
const formatDate=value=>Number.isFinite(Date.parse(value))?new Intl.DateTimeFormat('fr-FR',{dateStyle:'medium'}).format(new Date(value)):'À renseigner';
const btn=(label,task,value='',primary=false)=>`<button type="button" data-action="${task}" data-value="${esc(value)}" class="${primary?'primary':''}">${esc(label)}</button>`;
const durationText=minutes=>minutes>=60?`${Math.floor(minutes/60)} h${minutes%60?' '+minutes%60+' min':''}`:`${minutes} min`;
const empty=text=>`<p class="empty">${esc(text)}</p>`;
function url(blob){const value=URL.createObjectURL(blob);urls.push(value);return value;}
function photoFor(recipe){return book.photos.find(p=>p.id===recipe.photoId);}
function notice(text,error=false){message.hidden=false;message.classList.toggle('error',error);message.setAttribute('role',error?'alert':'status');message.textContent=text;}
function report(error){notice(friendlyStorageError(error),true);}
function clearNotice(){message.hidden=true;message.textContent='';}
function setBusy(value){busy=value;main.setAttribute('aria-busy',String(value));main.querySelectorAll('button,input,select,textarea').forEach(e=>e.disabled=value);}
function setContent(html,label='ÉCRIRE MA RECETTE',toolNames=['knife','mortar','grater'],variant=''){main.innerHTML=frame(label,html,{toolNames,variant});main.focus({preventScroll:true});}
function page(label,body,toolNames=[],variant=''){setContent(body,label,toolNames,variant);}
function navigate(route){if(location.hash===route)render();else location.hash=route;}
async function change(update,{redraw=true,text='Enregistré dans le carnet.'}={}){if(busy)return false;setBusy(true);try{const next=typeof update==='function'?update(structuredClone(book)):update;book=await store.commit(validateNotebook(next),book.revision);setBusy(false);if(redraw)render();if(text)notice(text);return true;}catch(error){setBusy(false);report(error);return false;}}
function picture(recipe){const p=photoFor(recipe);return p?`<img class="recipe-photo" src="${url(p.blob)}" alt="Photo de ${esc(recipe.title)}">`:art(recipe.art??'dish');}
function marked(){const r=book.recipes.find(r=>r.id===book.bookmarkedId);return `<section class="marked-page"><div><h2>Ma recette marquée</h2>${r?`<p class="hand">${esc(r.title)}</p>${action('Reprendre cette recette',`#recette/${r.id}`)}`:empty('Marquez une recette pour la retrouver ici.')}</div>${r?`<a class="herb-bookmark" href="#recette/${r.id}" aria-label="Retrouver ma recette marquée : ${esc(r.title)}">${art('rosemaryMarker')}<span class="hand">Ma recette</span></a>`:''}</section>`;}
function home(){
 const markedRecipe=book.recipes.find(r=>r.id===book.bookmarkedId);
 page('LE CARNET DE PIERRE',`<div class="cover-panel">${coverDecor()}<h1 class="cover-title">Mon carnet<br>de recettes<span class="cover-sub">Le carnet de Pierre</span></h1><div class="cover-pot">${art('cocotte')}</div><p class="cover-invitation hand">À vos tabliers !</p><div class="cover-open">${action('Ouvrir le carnet','#sommaire')}</div>${markedRecipe?`<a class="cover-herb" href="#recette/${markedRecipe.id}" aria-label="Retrouver ma recette marquée : ${esc(markedRecipe.title)}">${art('rosemaryMarker')}<span class="hand">Ma recette<br>marquée</span></a>`:''}</div>`,[],'cover closed-cover');
}
function index(){
 const rows=[['Le marché','Produits et idées','chapterMarket','#marche'],['Mon petit coin de verdure','Plantes et récoltes','chapterGarden','#jardin'],['Mes recettes','Assiettes, entrées et desserts','chapterRecipes','#recettes'],['Menu de la semaine','Les repas du midi et du soir','cocotte','#menus'],['Ma liste de courses','Les achats à prévoir','chapterShopping','#courses'],['Le garde-manger','Réserves et bocaux','chapterPantry','#garde-manger']];
 page('SOMMAIRE',`<div class="contents-title"><h1>Le carnet de Pierre</h1><span aria-hidden="true">— ● —</span></div><nav class="chapter-list" aria-label="Les chapitres du carnet">`+rows.map(([title,annotation,image,to])=>`<a class="chapter-row" href="${to}"><span class="chapter-picture">${art(image)}</span><span class="chapter-copy"><strong>${title}</strong><span class="hand">${annotation}</span></span><span class="chapter-arrow" aria-hidden="true">›</span></a>`).join('')+`</nav>`+marked()+`${book.cooking?`<aside class="cooking-resume"><span class="hand">Préparation en cours</span><strong>${esc(book.cooking.snapshot.title)}</strong><p>Étape ${book.cooking.stepIndex+1} / ${book.cooking.snapshot.steps.length}</p>${action('Reprendre en cuisine','#cuisine')}</aside>`:''}<a class="preferences-link" href="#preferences">Préférences et sauvegardes</a>`,[],'contents-page');
}
function recipeList(){
 page('MES RECETTES',`<label class="field">Un titre, un ingrédient…<input id="recipe-search" type="search" value="${esc(searchQuery)}"></label><div class="category-grid">${[['Entrées','bowl'],['Assiettes et plats','cocotte'],['Garnitures','carrots'],['Sauces et bases','gravy'],['Desserts','mold'],['Favoris','kettle']].map(([cat,image])=>`<button data-action="category" data-value="${cat}" class="${category===cat?'selected':''}">${art(image)}${cat==='Assiettes et plats'?'Plats et assiettes':cat}</button>`).join('')}</div>${action('Ajouter une recette','#nouvelle',true)}<div id="recipe-list"></div><div class="actions">${action('Menus de la semaine','#menus')}</div>${marked()}<p class="hand">${catalogueCount(book)} recettes dans le carnet de Pierre.</p>`,['mincer','sieve','mold']);
 const draw=()=>{const rs=searchRecipes(book,searchQuery).filter(r=>!category||(category==='Favoris'?book.favoriteIds.includes(r.id):r.category===category));document.querySelector('#recipe-list').innerHTML=rs.map(r=>`<a class="row row-link" href="#recette/${r.id}"><span class="number">${String(r.number).padStart(2,'0')}</span>${picture(r)}<div><h3>${esc(r.title)}</h3><p class="hand">${r.editorial?esc(r.editorial.family+' · '+r.editorial.season):r.isExample?'Exemple · à tester':r.status==='draft'?'Brouillon':'Fiche complète'}${book.favoriteIds.includes(r.id)?' · favori':''}</p></div></a>`).join('')||empty('Aucune recette ne correspond à cette recherche.');};draw();document.querySelector('#recipe-search').oninput=e=>{searchQuery=e.target.value;draw();};
}
function quantityLines(recipe,target,only=null){
 const items=recipe.ingredients.filter(i=>!only||only.includes(i.id));
 return `<ul class="ingredients">${items.map(i=>`<li><span class="name">${esc(i.name)}<span class="state">${esc(ingredientPreparation(recipe,i,target))}</span></span><span class="amount">${esc(displayQuantity(scaledQuantity(i,recipe.servings,target)))} ${i.quantity===null?'':esc(i.unit)}</span></li>`).join('')}</ul>`;
}
function expandedNote(recipe,target){return recipe.notes.replace(/\{\{quantite:([a-zA-Z0-9_-]+)\}\}/g,(_,key)=>{const i=recipe.ingredients.find(i=>i.id===key);return i?displayQuantity(scaledQuantity(i,recipe.servings,target))+' '+i.unit:'Quantité à renseigner';});}
function recipeEvidence(recipe){
 if(!recipe.editorial)return `<p class="help">${esc(recipe.origin)}</p>`;
 return `<p class="hand recipe-trial">${recipe.editorial.testedInKitchen?'Essayée en cuisine':'À essayer en cuisine'}</p><details class="recipe-origin"><summary>Origine de la fiche</summary><p>${esc(recipe.origin)}</p><p class="help">Fiche ${recipe.editorial.sourceNumber}${recipe.editorial.sourcePage?' · page '+recipe.editorial.sourcePage:''} du recueil fourni par Pierre.</p></details>`;
}
function detail(recipe,meal=null){
 const target=meal?.servings??servingsById.get(recipe.id)??(recipe.isExample?3:recipe.servings);if(!meal)servingsById.set(recipe.id,target);const alerts=exclusions(recipe,book.settings);
 const servings=meal?`<div class="servings"><strong>${meal.servings} convives · version ${recipe.version}</strong><p class="hand">Le repas garde la recette choisie dans le menu.</p>${action('Retour aux menus','#menus')}</div>`:`<div class="servings"><strong>Convives</strong>${btn('−','servings-minus',recipe.id)}<label><span class="status-note">Nombre</span><input id="target-servings" aria-label="Nombre de convives" type="number" min="1" max="100" step="1" value="${target}"></label>${btn('+','servings-plus',recipe.id)}<span class="hand">Base : ${recipe.servings} personnes.</span></div>`;
 page('MES RECETTES',`<p class="kicker">Fiche n° ${String(recipe.number).padStart(2,'0')}</p>${heading(recipe.title,recipe.editorial?recipe.editorial.family+' · '+recipe.editorial.season:recipe.isExample?'À tester en cuisine.':recipe.status==='draft'?'Brouillon':'Ma fiche complète')}${recipeEvidence(recipe)}<div class="recipe-hero">${picture(recipe)}<div>${btn(book.bookmarkedId===recipe.id?'Recette marquée':'Marquer la recette','bookmark',recipe.id)}${btn(book.favoriteIds.includes(recipe.id)?'★ Favori':'☆ Favori','favorite',recipe.id)}</div></div>${servings}${recipe.prepMinutes!=null||recipe.cookMinutes!=null?`<div class="grid"><p>Préparation : <strong>${recipe.prepMinutes??'À renseigner'}${recipe.prepMinutes==null?'':' min'}</strong></p><p>Cuisson : <strong>${recipe.cookMinutes??'À renseigner'}${recipe.cookMinutes==null?'':' min'}</strong></p></div>${recipe.editorial?.restMinutes?`<p>Repos / froid : <strong>${durationText(recipe.editorial.restMinutes)}</strong></p>`:''}<p class="help">${recipe.editorial?.collectionId?'Temps indicatifs ; adapter les plats, les fournées et l’épaisseur des préparations à la tablée.':recipe.editorial?'Compter environ '+recipe.editorial.totalMinutes+' min en préparant les garnitures pendant la cuisson.':recipe.isExample?'Temps illustratifs de la maquette, à vérifier en cuisine.':'Temps notés dans votre fiche ; ils ne sont pas multipliés avec les convives.'}</p>`:''}${section('Matériel',`<p class="hand">${esc(recipe.material||'À renseigner dans ma recette.')}</p>`,'cocotte')}<div id="recipe-ingredients"></div>${recipe.editorial&&!recipe.editorial.allergens.startsWith('Aucun des 14')?`<p class="help">Allergènes : ${esc(recipe.editorial.allergens)}</p>`:''}${alerts.length?`<div class="notice warning"><strong>Mes repères alimentaires</strong><ul>${alerts.map(a=>`<li>${esc(a)}</li>`).join('')}</ul><p class="help">Repérage indicatif par nom ; dérivés, compositions et traces à vérifier.</p></div>`:''}${recipe.editorial?section('La petite touche du chef',`<p class="hand">${esc(recipe.editorial.chefTip)}</p>`,'mortar'):''}${section(recipe.editorial?'Mes annotations':'La petite touche du chef',`<div class="hand lines" id="recipe-note"></div>`,recipe.editorial?'board':'mortar')}${section('Étapes et méthode',`<div id="recipe-method"></div>`)}<div class="actions">${btn('Passer en cuisine',meal?'cook-meal':'cook',meal?.id??recipe.id,true)}${meal?action('Voir la fiche actuelle du carnet',`#recette/${recipe.id}`):action('Modifier ma recette',`#modifier/${recipe.id}`)}</div>`,['copper','skimmer','pepper','citrus']);
 const draw=()=>{const n=meal?.servings??servingsById.get(recipe.id);document.querySelector('#recipe-ingredients').innerHTML=section(`Ingrédients pour ${n}`,ingredientGroups(recipe).map(c=>`<h3 class="kicker">${esc(c)}</h3>${quantityLines(recipe,n,recipe.ingredients.filter(i=>(i.group||i.component)===c).map(i=>i.id))}`).join('')||empty('À renseigner.'));document.querySelector('#recipe-note').textContent=expandedNote(recipe,n)||(recipe.editorial?'Le petit mot à garder pour la prochaine fois…':'');document.querySelector('#recipe-method').innerHTML=recipe.steps.length?`<ol class="steps">${recipe.steps.map((_,i)=>`<li>${esc(methodText(recipe,i,n))}</li>`).join('')}</ol><p class="help">${hasOriginalMethod(recipe)?'Les quantités suivent vos convives. Pour la cuisson, gardez l’œil sur la casserole.':'Une recette à votre main : ajustez les quantités dans vos notes si besoin.'}</p>`:empty('Les étapes restent à écrire.');};draw();if(!meal)document.querySelector('#target-servings').oninput=e=>{if(e.target.value&&e.target.validity.valid){servingsById.set(recipe.id,Number(e.target.value));draw();}};
}
function clock(ms){const seconds=Math.ceil(Math.max(0,ms)/1000);return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}
function kitchen(){
 const c=book.cooking;if(!c){page('À VOS TABLIERS !',heading('La cuisine vous attend')+empty('Ouvrez une recette puis choisissez « Passer en cuisine ».')+action('Mes recettes','#recettes'));return;}
 const r=c.snapshot,only=r.stepIngredients?.[c.stepIndex]??null;
 page('À VOS TABLIERS !',heading(r.title)+`<p style="text-align:center">${c.servings} convives · version ${r.version} · Étape ${c.stepIndex+1} / ${r.steps.length}</p><div class="step-progress" aria-label="Progression">${r.steps.map((_,i)=>`<span class="step-dot ${c.completed.includes(i)||i===c.stepIndex?'done':''}" aria-hidden="true"></span>`).join('')}</div><p class="cooking-step">${esc(methodText(r,c.stepIndex,c.servings))}</p><p class="hand" style="text-align:center">${/fondre|feu/.test(r.steps[c.stepIndex])?'À feu doux, remuer et surveiller.':'Un geste après l’autre.'}</p><p class="help">${hasOriginalMethod(r)?'Les quantités sont ajustées pour votre tablée.':'La liste ci-dessous suit votre tablée ; gardez vos repères de cuisson.'}</p>${section(only?'Ingrédients de cette étape':'Ingrédients de la recette',quantityLines(r,c.servings,only))}<div class="timer-layout retro-layout">${retroTimer(c.timer)}<div class="timer-actions"><p class="timer-title">Durée choisie : <span id="timer-duration">${c.timer.durationMs/60000}</span> min</p><span class="time-left" id="timer-label"></span><div class="actions">${btn(c.timer.running?'Pause':'Lancer','timer-toggle')}${btn('Régler','show-timer')}</div>${btn('Remettre à zéro','timer-reset')}</div></div><form id="timer-form" class="inline-form" hidden><label class="field">Durée en minutes<input name="minutes" type="number" min="0.0166667" max="1440" step="any" value="${c.timer.durationMs/60000}"></label><label class="field">Nom du minuteur<input name="timerName" maxlength="120" value="${esc(c.timer.name)}"></label><button class="primary">Enregistrer la durée</button></form><div class="actions">${btn('Étape précédente','previous-step')}${btn(c.stepIndex===r.steps.length-1?'Préparation terminée':'Étape terminée','next-step','',true)}</div><label class="check"><input id="keep-awake" type="checkbox"${book.settings.keepAwake?' checked':''}><span>Garder l’écran allumé</span></label><p class="help" id="awake-status">Selon les possibilités du téléphone.</p><p class="help">Le temps suit l’heure de fin, même après une mise en veille. La sonnerie n’est pas garantie quand le navigateur est fermé ou suspendu.</p><p class="hand">Ça mijote…</p>${action(c.menuId&&book.menus.some(m=>m.id===c.menuId)?'Retour au repas prévu':'Retour à la recette',c.menuId&&book.menus.some(m=>m.id===c.menuId)?`#repas/${c.menuId}`:`#recette/${r.id}`)}`,['masher','ladle']);
 document.querySelector('#timer-form').onsubmit=async e=>{e.preventDefault();const seconds=Number(e.target.elements.minutes.value)*60,name=e.target.elements.timerName.value.trim();await change(n=>{n.cooking.timer=timerAction(n.cooking.timer,'set',seconds);n.cooking.timer.name=name;return n;},{text:'Durée du minuteur enregistrée.'});};
 wireTimerDial({getTimer:()=>book.cooking.timer,isBusy:()=>busy,onSet:seconds=>change(n=>{n.cooking.timer=timerAction(n.cooking.timer,'set',seconds);return n;},{redraw:false,text:'Durée réglée avec la molette.'}),onToggle:async()=>{await soundReady();return change(n=>{n.cooking.timer=timerAction(n.cooking.timer,n.cooking.timer.running?'pause':'start');return n;},{text:'Minuteur enregistré.'});}});
 document.querySelector('#keep-awake').onchange=async e=>{const enabled=e.target.checked;if(await change(n=>{n.settings.keepAwake=enabled;return n;},{redraw:false,text:''}))await updateWakeLock();};tick();updateWakeLock();
}
const products=[{id:'carotte',name:'La carotte',plural:'Carottes',art:'carrots',annotation:'Croquantes et colorées.',association:'Volaille, lentilles et herbes aromatiques.'},{id:'courge',name:'La courge',plural:'Courge',art:'pumpkin',annotation:'Douce et savoureuse.',association:'Garnitures et soupes à composer.'},{id:'champignon',name:'Le champignon',plural:'Champignons',art:'mushrooms',annotation:'Parfaits en poêlée.',association:'Préparations et sauces à composer.'},{id:'poireau',name:'Le poireau',plural:'Poireaux',art:'leek',annotation:'Du marché à l’assiette.',association:'Cabillaud et lentilles.'}];
function market(){page('LE MARCHÉ',heading('Au retour du marché…')+`<label class="field">Un produit ou une idée…<input id="product-search" type="search"></label><div id="products"></div>${section('Mon panier d’envies',`<div class="row">${art('marketBasket')}<div><p>Les produits choisis apparaissent dans mes articles personnels.</p>${action('Voir mes courses','#courses')}</div></div><p class="hand">Une envie n’est pas encore une réserve.</p><form id="purchase-form"><label class="field">Achat à confirmer<select name="article">${book.shopping.personal.map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('')}</select></label><button${book.shopping.personal.length?'':' disabled'}>Confirmer un achat</button><p class="help">Les achats confirmés sont cochés dans les courses ; une réserve se note séparément.</p></form>`)}`,['board','knife']);const draw=q=>document.querySelector('#products').innerHTML=products.filter(p=>p.plural.toLowerCase().includes(q.toLowerCase())).map(p=>`<a class="row row-link" href="#produit/${p.id}">${art(p.art)}<div><h2>${p.plural}</h2><p class="hand">${p.annotation}</p><span class="button">Voir les recettes →</span></div></a>`).join('');draw('');document.querySelector('#product-search').oninput=e=>draw(e.target.value);document.querySelector('#purchase-form').onsubmit=async e=>{e.preventDefault();const key=e.target.elements.article.value;await change(n=>{const row=n.shopping.personal.find(r=>r.id===key);if(!row)throw new Error('Ajoutez d’abord un produit aux courses.');row.bought=true;return n;},{text:'Achat confirmé et coché dans les courses.'});};}
function product(p){page('LE MARCHÉ',heading(p.name,'Un classique du carnet.')+`<div class="row">${art(p.art)}<div><h2>En cuisine</h2><p class="hand">${p.annotation}</p></div></div>${section('Les associations du carnet',`<p class="hand">${p.association}</p>`,'cocotte')}${section('La petite touche du chef','<p class="hand">Un filet d’huile d’olive, une pincée de thym… À adapter à la préparation.</p>','mortar')}${section('À documenter','<p class="hand">Origine · saison · fraîcheur · conservation.</p><p class="help">Aucune source n’a encore été associée à cette fiche produit.</p>')}${btn('Retrouver mes recettes liées','product-recipes',p.plural)}${section('Prévoir dans mes courses',`<form id="product-form"><label class="field">Quantité à choisir<input name="quantity" type="number" min="0.000001" step="any" required></label><label class="field">Unité<select name="unit">${options(UNITS,'g')}</select></label><button class="primary">Ajouter aux courses</button></form><p class="help">L’ajout est un article personnel ; il ne crée pas une réserve.</p>`,'marketBasket')}`,['mandoline','grater','gravy']);document.querySelector('#product-form').onsubmit=async e=>{e.preventDefault();const f=e.target;await change(n=>{n.shopping.personal.push({id:id(),name:p.plural,quantity:Number(f.elements.quantity.value),unit:f.elements.unit.value,bought:false,atHome:false});return n;},{text:'Produit ajouté à vos articles personnels.'});};}
function garden(){const plants=book.plants.filter(p=>p.space===plantSpace);page('MON JARDIN',heading('Mon petit coin de verdure','Ça commence avec un pot.')+`<div class="cover-objects">${art('basil')}${art('watering')}${art('strawberry')}</div>${gardenGuideCards()}<div class="actions">${['Pot','Jardinière','Jardin'].map(s=>btn(s,'space',s,plantSpace===s)).join('')}</div>${plants.map(p=>`<a class="row row-link" href="#plante/${p.id}">${art(p.kind==='fraisier'?'strawberry':'basil')}<div><h2>${esc(p.name)}</h2><p class="hand">${esc(p.space)} · ${esc(p.location)}</p></div></a>`).join('')||empty('Aucune plante dans cet espace.')}${btn('Ajouter une plante','add-plant')}${plantForm()}${section('Mes observations',book.observations.length?book.observations.slice(-3).map(o=>`<p class="lines">${esc(o.text)}<span class="state">${formatDate(o.date)}</span></p>`).join(''):empty('Mes notes du jardin…'))}${section('Ma récolte',book.harvests.length?book.harvests.slice(-3).map(h=>`<div class="row">${art('berries')}<div><strong>${esc(book.plants.find(p=>p.id===h.plantId)?.name)}</strong><p>${displayQuantity(h.quantity)} ${esc(h.unit)}</p>${btn('Vers les réserves','harvest-reserve',h.id)}</div></div>`).join(''):empty('Aucune récolte notée pour le moment.'))}`,['board','basket']);wirePlantForm();}
function plantForm(plant){return `<form class="inline-form" id="plant-form" hidden><h2>${plant?'Mon installation':'Ajouter une plante'}</h2><label class="field">Nom<input name="name" maxlength="160" required value="${esc(plant?.name)}"></label><label class="field">Plante<select name="kind">${[['basilic','Basilic'],['fraisier','Fraisier'],['autre','Autre plante']].map(([value,label])=>`<option value="${value}"${plant?.kind===value?' selected':''}>${label}</option>`).join('')}</select></label><div class="grid"><label class="field">Installation<select name="space">${options(['Pot','Jardinière','Jardin'],plant?.space??plantSpace)}</select></label><label class="field">Emplacement<input name="location" maxlength="300" value="${esc(plant?.location)}" placeholder="Intérieur, terrasse…"></label></div><label class="field">Variété, si je la connais<input name="variety" maxlength="120" value="${esc(plant?.variety)}"></label><label class="field">Installation le<input name="installedOn" type="date" value="${esc(plant?.installedOn)}"></label><label class="field">Lumière et exposition observées<input name="exposure" maxlength="300" value="${esc(plant?.exposure)}"></label><div class="grid"><label class="field">Largeur du pot (cm)<input name="potWidthCm" type="number" min="0.1" max="1000" step="any" value="${plant?.potWidthCm??''}"></label><label class="field">Profondeur du pot (cm)<input name="potDepthCm" type="number" min="0.1" max="1000" step="any" value="${plant?.potDepthCm??''}"></label></div><label class="field">Écoulement de l’eau<input name="drainage" maxlength="300" value="${esc(plant?.drainage)}" placeholder="Pot percé, soucoupe vidée…"></label><label class="field">Ma référence ou mon livre<input name="source" maxlength="1500" value="${esc(plant?.source)}" placeholder="Référence ou URL"></label><label class="field">Mes notes<textarea name="notes" maxlength="12000">${esc(plant?.notes)}</textarea></label><button class="primary">Enregistrer la plante</button></form>`;}
function wirePlantForm(plant){document.querySelector('#plant-form').onsubmit=async e=>{e.preventDefault();const f=e.target;const row={...plant,id:plant?.id??id(),name:f.elements.name.value.trim(),kind:f.elements.kind.value,space:f.elements.space.value,location:f.elements.location.value.trim(),source:f.elements.source.value.trim(),notes:f.elements.notes.value,variety:f.elements.variety?.value.trim()??'',installedOn:f.elements.installedOn?.value??'',exposure:f.elements.exposure?.value.trim()??'',potWidthCm:f.elements.potWidthCm?.value?Number(f.elements.potWidthCm.value):null,potDepthCm:f.elements.potDepthCm?.value?Number(f.elements.potDepthCm.value):null,drainage:f.elements.drainage?.value.trim()??''};if(await change(n=>{n.plants=n.plants.filter(p=>p.id!==row.id);n.plants.push(row);return n;},{redraw:false,text:'Plante enregistrée.'})){plantSpace=row.space;navigate('#plante/'+row.id);}};}
function gardenGuide(kind){
 const g=GARDEN_GUIDES[kind];if(!g){garden();return;}
 page('MON JARDIN',heading(g.title)+`<div class="cover-objects">${art(g.art)}${art('watering')}</div>`+section('Les gestes du jardinier',plantAdvice(kind),'herbs')+section('Du jardin à la cuisine',recipeLinks(book,g.search))+`<details><summary>Noter mon plant dans le carnet</summary>${plantForm({name:g.name,kind,space:plantSpace}).replace(' hidden>','>')}</details>${action('Retour au jardin','#jardin')}`,['board','basket']);wirePlantForm();
}
function plant(p){
 const observations=book.observations.filter(o=>o.plantId===p.id),harvests=book.harvests.filter(h=>h.plantId===p.id);
 page('MON JARDIN',heading(p.name)+`<div class="plant-hero">${art(p.kind==='fraisier'?'strawberry':'basil')}<div><h2>Mon installation</h2><p>${esc(p.space)}</p><p>${esc(p.location||'Emplacement à noter')}</p><p class="hand">${esc([p.variety,p.exposure].filter(Boolean).join(' · '))}</p>${btn('Adapter à mon espace','edit-plant')}</div></div>${plantForm(p)}`+
 section('Les gestes du jardinier',plantAdvice(p.kind)+(p.source?`<details><summary>Mon livre, ma référence</summary><p>${esc(p.source)}</p></details>`:''),'herbs')+
 section('Mes notes',`<p class="hand lines">${esc(p.notes)}</p>`+observations.map(o=>`<p class="lines">${esc(o.text)}<span class="state">${formatDate(o.date)}</span></p>`).join('')+`<form id="observation-form"><label class="field">La terre aujourd’hui<select name="soil">${options(['À observer','Sèche','Humide','Détrempée'],'À observer')}</select></label><label class="field">Mon observation et mon geste<textarea name="text" maxlength="4000" placeholder="J’ai arrosé au pied, retiré les fleurs…"></textarea></label><label class="field">Date<input name="date" type="date" required value="${dayString()}"></label><button>Noter mon observation</button></form>`,'board')+
 section('Mes récoltes',harvests.map(h=>`<div class="row"><div><p>${displayQuantity(h.quantity)} ${esc(h.unit)} · ${formatDate(h.date)}</p>${btn(book.reserves.some(r=>r.harvestId===h.id)?'Déjà dans les réserves':'Garder en réserve','harvest-reserve',h.id)}</div></div>`).join('')+`<p class="hand">Même une petite poignée mérite sa ligne dans le carnet.</p><form id="harvest-form"><div class="grid"><label class="field">Quantité récoltée<input name="quantity" type="number" min="0.000001" step="any" placeholder="Laisser vide si inconnue"></label><label class="field">Unité<select name="unit">${options(['g','kg','pièce'],'g')}</select></label></div><label class="field">Date de récolte<input name="date" type="date" required value="${dayString()}"></label><button>Noter une récolte</button></form><p class="help">Des fruits comptés restent des fruits comptés : pas de poids inventé.</p>`,'basket')+
 section('Du jardin à la cuisine',recipeLinks(book,p.kind==='fraisier'?'fraise':p.kind)+(p.kind==='fraisier'?`<p>${action('Ma fiche de confiture','#preparation/'+(book.preparations.find(p=>p.referenceId==='GM01')?.id??'pantry-GM01'))}</p>`:'')),['bottle','funnel']);
 wirePlantForm(p);
 document.querySelector('#observation-form').onsubmit=async e=>{e.preventDefault();const f=e.target,soil=f.elements.soil?.value??'À observer',text=[soil==='À observer'?'':'Terre '+soil.toLowerCase()+'.',f.elements.text.value.trim()].filter(Boolean).join(' ');if(!text){notice('Noter un geste ou observer la terre.',true);return;}await change(n=>{n.observations.push({id:id(),plantId:p.id,text,date:f.elements.date.value});return n;},{text:'Une ligne de plus au jardin.'});};
 document.querySelector('#harvest-form').onsubmit=async e=>{e.preventDefault();const f=e.target,row={id:id(),plantId:p.id,quantity:f.elements.quantity.value===''?null:Number(f.elements.quantity.value),unit:f.elements.unit.value,date:f.elements.date.value};await change(n=>{n.harvests.push(row);return n;},{text:'Récolte notée. À cuisiner ou à garder en réserve.'});};
}

function ingredientRows() {
  return draft.ingredients.map((item,index) => `<div class="ingredient-row" data-ingredient="${esc(item.id)}"><div class="row-title"><strong>Ingrédient ${index+1}</strong><button type="button" data-remove-ingredient="${esc(item.id)}" aria-label="Retirer l’ingrédient ${index+1}">Retirer</button></div>
    <label class="field">Nom<input data-key="name" maxlength="200" value="${esc(item.name)}" placeholder="Ex. lentilles vertes"></label>
    <div class="row-grid"><label class="field">Quantité<input data-key="quantity" type="number" inputmode="decimal" step="any" min="0.000001" max="1000000" value="${item.quantity ?? ''}" placeholder="À préciser"></label><label class="field">Unité<select data-key="unit">${options(UNITS,item.unit)}</select></label>
    <label class="field">État<select data-key="state">${options(STATES,item.state)}</select></label><label class="field">Préparation<select data-key="component">${options(COMPONENTS,item.component)}</select></label></div><label class="field">Précision de pesée<input data-key="preparation" maxlength="300" value="${esc(item.preparation)}" placeholder="Cru, sans arêtes ; sec ; cuit et égoutté…"></label><label class="field">Groupe dans la recette<input data-key="group" maxlength="100" value="${esc(item.group)}" placeholder="Poisson, lentilles, finition…"></label><button type="button" data-note-for="${esc(item.id)}">Insérer sa quantité dans mes notes</button></div>`).join('');
}
function stepRows() {
  return draft.steps.map((step,index) => `<div class="step-row" data-step="${index}"><div class="row-title"><strong>Étape ${index+1}</strong><button type="button" data-remove-step="${index}" aria-label="Retirer l’étape ${index+1}">Retirer</button></div><label class="field">Déroulement<textarea data-step-text maxlength="4000" placeholder="Le geste, la cuisson, le résultat attendu…">${esc(culinaryMethod(draft,index))}</textarea></label></div>`).join('');
}
function captureDraft() {
  const form = document.querySelector('#recipe-form'); if (!form) return;
  draft.title=form.elements.title.value; draft.servings=Number(form.elements.servings.value); draft.category=form.elements.category.value;
  draft.status=form.elements.status.value; draft.origin=form.elements.origin.value; draft.notes=form.elements.notes.value; draft.material=form.elements.material.value; draft.prepMinutes=form.elements.prepMinutes.value===''?null:Number(form.elements.prepMinutes.value); draft.cookMinutes=form.elements.cookMinutes.value===''?null:Number(form.elements.cookMinutes.value);
  draft.ingredients=[...form.querySelectorAll('[data-ingredient]')].map(row => {
    const item = {...draft.ingredients.find(i=>i.id===row.dataset.ingredient),id:row.dataset.ingredient}; row.querySelectorAll('[data-key]').forEach(input => item[input.dataset.key] = input.dataset.key === 'quantity' ? input.value === '' ? null : Number(input.value) : input.value.trim()); return item;
  });
  draft.steps=[...form.querySelectorAll('[data-step-text]')].map(input => input.value.trim());
}
function updateRows() { document.querySelector('#ingredient-rows').innerHTML=ingredientRows(); document.querySelector('#step-rows').innerHTML=stepRows(); }
function editor(recipe) {
  draft = structuredClone(recipe ?? blankRecipe()); photoFile = undefined; removePhoto = false; dirty = false;
  const existing = recipe && photoFor(recipe);
  setContent(`<p class="eyebrow">${recipe ? `Fiche ${recipe.number} · modification` : 'Une nouvelle page'}</p><h1>${recipe ? 'Modifier ma recette' : 'Écrire ma recette'}</h1><p class="muted">Un titre suffit pour conserver un brouillon. Les ingrédients et les étapes viendront à votre rythme.</p>
    <form id="recipe-form"><fieldset class="form-section"><legend>La fiche</legend>
    <label class="field">Titre de la recette<input name="title" maxlength="160" required value="${esc(draft.title)}" placeholder="Ex. tarte aux poireaux de la maison"></label>
    <div class="grid"><label class="field">Convives de référence<input name="servings" type="number" min="1" max="100" step="1" inputmode="numeric" required value="${draft.servings}"></label><label class="field">Catégorie<select name="category">${options(CATEGORIES,draft.category)}</select></label></div>
    <label class="field">État de la fiche<select name="status"><option value="draft"${draft.status==='draft'?' selected':''}>Brouillon</option><option value="ready"${draft.status==='ready'?' selected':''}>Prête à cuisiner</option></select></label><p class="help">« Prête » : les ingrédients sont notés, les étapes sont écrites. À vos tabliers !</p>
    <details><summary>Matériel et temps de la préparation</summary><label class="field">Matériel<input name="material" maxlength="1000" value="${esc(draft.material)}"></label><div class="grid"><label class="field">Préparation (minutes)<input name="prepMinutes" type="number" min="0" max="1440" step="1" value="${draft.prepMinutes??''}"></label><label class="field">Cuisson (minutes)<input name="cookMinutes" type="number" min="0" max="1440" step="1" value="${draft.cookMinutes??''}"></label></div></details><label class="field">Origine de la recette (facultatif)<input name="origin" maxlength="1000" value="${esc(draft.origin)}" placeholder="Mon essai, recette de famille, livre et page…"></label></fieldset>
    <fieldset class="form-section"><legend>Les ingrédients</legend><p class="help">Regroupez-les entre préparation principale, garniture, sauce et finition. Une quantité vide restera « À préciser ».</p><div id="ingredient-rows">${ingredientRows()}</div><button type="button" id="add-ingredient">+ Ajouter un ingrédient</button></fieldset>
    <fieldset class="form-section"><legend>Le tour de main</legend><div id="step-rows">${stepRows()}</div><button type="button" id="add-step">+ Ajouter une étape</button></fieldset>
    <fieldset class="form-section"><legend>La photo et mes notes</legend><div id="photo-preview">${existing ? `<img class="photo-preview" src="${url(existing.blob)}" alt="Photo de cette recette">` : ''}</div>
    <label class="field">Photo personnelle (facultatif)<input id="photo-file" type="file" accept="image/jpeg,image/png,image/webp"></label><p class="help">La photo est adaptée au téléphone : 1 600 pixels maximum, puis conservée dans les sauvegardes. Gardez le fichier original à part.</p><button type="button" id="remove-photo"${existing?'':' hidden'}>Retirer la photo</button>
    <p class="help">Une quantité calculée peut être insérée depuis la ligne de son ingrédient. Elle suivra les convives dans la fiche.</p><label class="field">Mes annotations<textarea name="notes" maxlength="12000" placeholder="La prochaine fois, un peu plus de thym…">${esc(draft.notes)}</textarea></label></fieldset>
    
    <div class="save-bar"><button type="submit" class="primary">Enregistrer le brouillon</button><p class="help" id="save-state" role="status">Votre saisie sera conservée après l’enregistrement.</p></div></form><div class="actions"><a class="button" href="${recipe?`#recette/${esc(recipe.id)}`:'#carnet'}">Annuler et revenir</a></div>`);
  const form=document.querySelector('#recipe-form');
  form.addEventListener('input',()=>{dirty=true; document.querySelector('#save-state').textContent='Modifications à enregistrer.';});
  form.addEventListener('change',()=>{dirty=true;});
  form.addEventListener('click', event=> {
    const button=event.target.closest('button'); if (!button || busy) return;
    if (button.id==='add-ingredient') {captureDraft(); if(draft.ingredients.length>=150){notice('Cette fiche contient déjà 150 ingrédients.',true);return;} draft.ingredients.push({id:id(),name:'',quantity:null,unit:'g',state:STATES[0],component:COMPONENTS[0]}); dirty=true; updateRows();document.querySelector('[data-ingredient]:last-child input')?.focus();}
    if (button.dataset.removeIngredient) {captureDraft();draft.ingredients=draft.ingredients.filter(i=>i.id!==button.dataset.removeIngredient);dirty=true;updateRows();document.querySelector('#add-ingredient').focus();}
    if (button.id==='add-step') {captureDraft();if(draft.steps.length>=100){notice('Cette fiche contient déjà 100 étapes.',true);return;}draft.steps.push('');dirty=true;updateRows();document.querySelector('[data-step]:last-child textarea')?.focus();}
    if (button.dataset.removeStep !== undefined) {captureDraft();draft.steps.splice(Number(button.dataset.removeStep),1);dirty=true;updateRows();document.querySelector('#add-step').focus();}
    if (button.dataset.noteFor) {const input=form.elements.notes;input.value+=(input.value?'\n':'')+'{{quantite:'+button.dataset.noteFor+'}}';dirty=true;input.focus();}
    if (button.id==='remove-photo') {photoFile=undefined;removePhoto=true;dirty=true;document.querySelector('#photo-file').value='';document.querySelector('#photo-preview').innerHTML='';button.hidden=true;}
  });
  document.querySelector('#photo-file').addEventListener('change',event=> {
    const file=event.target.files[0];if(!file)return;
    if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15*1024*1024){notice('Choisissez une photo JPEG, PNG ou WebP de moins de 15 Mo.',true);event.target.value='';return;}
    photoFile=file;removePhoto=false;dirty=true;document.querySelector('#photo-preview').innerHTML=`<img class="photo-preview" src="${url(file)}" alt="Aperçu de la photo choisie">`;document.querySelector('#remove-photo').hidden=false;
  });
  form.addEventListener('submit',async event=> {
    event.preventDefault();if(busy)return;captureDraft();
    const candidate=structuredClone(draft);candidate.ingredients=candidate.ingredients.filter(i=>i.name || i.quantity!==null);candidate.steps=candidate.steps.filter(Boolean); if (candidate.stepIngredients && (candidate.steps.length!==recipe?.steps.length || candidate.ingredients.length!==recipe?.ingredients.length)) delete candidate.stepIngredients;
    setBusy(true);document.querySelector('#save-state').textContent='Enregistrement en cours…';
    try {
      const photo=photoFile?await preparePhoto(photoFile):removePhoto?null:undefined;
      const next=withRecipe(book,candidate,photo);book=await store.commit(next,book.revision);dirty=false;photoFile=undefined;
      busy=false;navigate(`#recette/${candidate.id}`);setTimeout(()=>notice('Recette enregistrée sur cet appareil.'),0);
    } catch(error) {setBusy(false);document.querySelector('#save-state').textContent='Échec : la saisie reste ici. Corrigez le problème puis réessayez.';report(error);}
  });
}

function menus(){
 const days=Array.from({length:7},(_,i)=>shiftDay(week,i));
 page('MES MENUS',heading('La petite semaine')+`<div class="actions">${btn('‹ Semaine précédente','week-prev')}<span class="ribbon">${formatDate(week)}</span>${btn('Semaine suivante ›','week-next')}</div><p class="hand">Semaine en construction</p><div id="menu-editor" hidden></div>${days.map(day=>`<section class="menu-day"><h2>${new Intl.DateTimeFormat('fr-FR',{weekday:'long',day:'numeric'}).format(new Date(day+'T12:00:00'))}</h2>${['Midi','Soir'].map(slot=>{const m=book.menus.find(m=>m.date===day&&m.slot===slot);return `<div class="meal"><span>${slot} :</span><div>${m?`<a class="meal-title" href="#repas/${m.id}">${esc(m.snapshot.title)}</a><p class="hand">${m.servings} convives · version ${m.snapshot.version}</p><div class="meal-controls">${btn('Modifier','menu-choose',day+'|'+slot)}${btn('Retirer','menu-remove',m.id)}</div>`:btn('Choisir une recette →','menu-choose',day+'|'+slot)}</div></div>`;}).join('')}</section>`).join('')}<div class="actions">${btn('Générer les courses','generate-courses','',true)}</div><p class="hand">On prépare, on partage, on se régale.</p><p class="help">Chaque repas garde la version de la recette choisie. Modifier une recette ne change pas silencieusement ce menu : choisissez-la de nouveau pour le mettre à jour.</p>`,['cocotte','carrots','madeleine']);
}
function menuEditor(value){const [date,slot]=value.split('|'),current=book.menus.find(m=>m.date===date&&m.slot===slot),holder=document.querySelector('#menu-editor');holder.hidden=false;holder.innerHTML=`<form id="menu-form" class="inline-form"><h2>${formatDate(date)} · ${slot}</h2><div class="grid"><label class="field">Date du repas<input name="date" type="date" required value="${date}"></label><label class="field">Repas<select name="slot">${options(['Midi','Soir'],slot)}</select></label></div><label class="field">Recette<select name="recipe" required>${book.recipes.map(r=>`<option value="${r.id}"${current?.recipeId===r.id?' selected':''}>${esc(r.title)}${r.status==='draft'?' · brouillon':''}</option>`).join('')}</select></label><label class="field">Convives<input name="servings" type="number" min="1" max="100" step="1" required value="${current?.servings??2}"></label>${current?`<label class="check"><input name="refreshRecipe" type="checkbox"><span>Reprendre la version actuelle du carnet</span></label><p class="help">Sans cocher, ce repas conserve sa version si vous gardez la même recette. Choisir une autre recette utilise sa fiche actuelle.</p>`:''}<button class="primary">Enregistrer le repas</button>${btn('Annuler','cancel-menu')}</form>`;holder.scrollIntoView({block:'nearest'});document.querySelector('#menu-form').onsubmit=async e=>{e.preventDefault();const f=e.target;const nextDate=f.elements.date.value,nextSlot=f.elements.slot.value;const occupied=book.menus.find(m=>m.date===nextDate&&m.slot===nextSlot&&m.id!==current?.id);if(occupied&&!confirm('Un repas est déjà prévu à cette date. Le remplacer ?'))return;await change(n=>{return setMenu(n,{date:nextDate,slot:nextSlot,recipeId:f.elements.recipe.value,servings:Number(f.elements.servings.value),menuId:current?.id,refreshRecipe:f.elements.refreshRecipe?.checked??false});},{text:'Repas enregistré avec sa version de recette.'});};}
function shoppingRow(row,personal){return `<div class="shopping-item ${row.bought?'bought':''}"><label><input type="checkbox" data-shopping="${row.id}" data-personal="${personal}"${row.bought?' checked':''}><span class="item-name">${esc(row.name)}${row.state?`<span class="state">${esc(row.state)}</span>`:''}${row.needsReview?'<small>Quantité augmentée : à vérifier.</small>':''}</span></label><span class="amount">${esc(displayQuantity(row.quantity))} ${row.quantity===null?'':esc(row.unit)}</span>${btn(row.atHome?'À la maison':'Déjà là ?','at-home',`${personal?'personal':'generated'}|${row.id}`)}</div>`;}
function courses(){
 const rows=book.shopping.generated,groups=[...new Set(rows.map(r=>r.aisle))];
 page('LISTE DE COURSES',heading('Mon panier à préparer')+`<p class="hand">${book.shopping.week?'Semaine du '+formatDate(book.shopping.week):'À composer depuis mes menus.'}</p>${art('marketBasket','market-illustration')}`+groups.map(group=>section(group,rows.filter(r=>r.aisle===group&&!r.atHome).map(r=>shoppingRow(r,false)).join('')||empty('Déjà à la maison.'))).join('')+(rows.length?'':empty('Choisissez des repas puis générez les courses.'))+section('Déjà à la maison',rows.filter(r=>r.atHome).map(r=>shoppingRow(r,false)).join('')||'<p class="hand">À renseigner…</p>')+section('Mes articles personnels',book.shopping.personal.map(r=>shoppingRow(r,true)).join('')+`<form id="personal-form"><label class="field">Ajouter un article<input name="name" maxlength="200" required placeholder="Papier cuisson…"></label><div class="grid"><label class="field">Quantité<input name="quantity" type="number" min="0" step="any" placeholder="À préciser"></label><label class="field">Unité<input name="unit" maxlength="40" required value="pièce"></label></div><button>Ajouter aux courses</button></form>`)+`<div class="actions">${btn('Actualiser depuis les menus','refresh-courses')}${btn('Copier la liste','copy-courses')}</div><div class="actions">${action('Mes menus','#menus')}${action('Noter une réserve réelle','#garde-manger')}</div><p class="hand">Les articles personnels restent conservés.</p>`,['basket','pepper','board']);
 document.querySelectorAll('[data-shopping]').forEach(input=>input.onchange=async e=>{const checked=e.target.checked,key=e.target.dataset.personal==='true'?'personal':'generated',rowId=e.target.dataset.shopping;await change(n=>{const r=n.shopping[key].find(r=>r.id===rowId);r.bought=checked;r.needsReview=false;return n;},{text:checked?'Achat coché.':'Achat décoché.'});});
 document.querySelector('#personal-form').onsubmit=async e=>{e.preventDefault();const f=e.target,row={id:id(),name:f.elements.name.value.trim(),quantity:f.elements.quantity.value===''?null:Number(f.elements.quantity.value),unit:f.elements.unit.value.trim(),bought:false,atHome:false};await change(n=>{n.shopping.personal.push(row);return n;},{text:'Article personnel enregistré.'});};
}
function reserveForm(reserve){return `<form id="reserve-form" class="inline-form"${reserve?'':' hidden'}><h2>${reserve?'Modifier une réserve':'Noter une réserve'}</h2><label class="field">Ce que j’ai réellement<input name="name" maxlength="200" required value="${esc(reserve?.name)}"></label><div class="grid"><label class="field">Quantité<input name="quantity" type="number" min="0" step="any" value="${reserve?metricQuantity(reserve.quantity,reserve.unit).quantity??'':''}" placeholder="À renseigner"></label><label class="field">Unité<input name="unit" maxlength="40" required value="${esc(reserve?metricQuantity(reserve.quantity,reserve.unit).unit:'g')}"></label></div><label class="field">État<input name="state" maxlength="80" value="${esc(reserve?.state??'à renseigner')}"></label><label class="field">Lot (facultatif)<input name="lot" maxlength="100" value="${esc(reserve?.lot)}"></label><label class="field">Date notée<input name="date" type="date" required value="${reserve?.date??dayString()}"></label><label class="field">Mes notes<textarea name="notes" maxlength="12000">${esc(reserve?.notes)}</textarea></label><p class="help">Les conditions et durées de conservation restent à documenter. Aucune durée sûre n’est déduite de cette saisie.</p><button class="primary">Enregistrer la réserve</button></form>`;}
function wireReserveForm(reserve){document.querySelector('#reserve-form').onsubmit=async e=>{e.preventDefault();const f=e.target,row={...reserve,id:reserve?.id??id(),name:f.elements.name.value.trim(),quantity:f.elements.quantity.value===''?null:Number(f.elements.quantity.value),unit:f.elements.unit.value.trim(),state:f.elements.state.value.trim(),lot:f.elements.lot.value.trim(),date:f.elements.date.value,harvestId:reserve?.harvestId??null,notes:f.elements.notes.value};if(reserve&&row.unit===metricQuantity(reserve.quantity,reserve.unit).unit&&row.unit!==reserve.unit){row.quantity=row.quantity===null?null:fromMetricQuantity(row.quantity,reserve.unit);row.unit=reserve.unit;}await change(n=>{n.reserves=n.reserves.filter(r=>r.id!==row.id);n.reserves.push(row);return n;},{text:'Réserve enregistrée avec son statut de conservation à documenter.'});};}
function pantry(){
 const manual=book.reserves.filter(r=>!r.pantryLotId),lots=book.pantryLots??[];
 page('LE GARDE-MANGER',heading('Les bonnes réserves','Une étiquette raconte son histoire.')+`<div class="cover-objects">${art('berries')}${art('jar')}${art('copper')}</div><div class="actions">${btn('Mes réserves','scroll-reserves')}${btn('Fiches à préparer','scroll-preparations')}</div>`+
 section('Ce que j’ai réellement',`<div id="reserve-list">${manual.map(r=>`<div class="row">${art(r.name.toLowerCase().includes('fraise')?'berries':'jar')}<div><h3>${esc(r.name)}</h3><p>${displayQuantity(metricQuantity(r.quantity,r.unit).quantity)} ${r.quantity===null?'':esc(metricQuantity(r.quantity,r.unit).unit)} ${r.lot?'· lot '+esc(r.lot):''}</p>${action('Ouvrir ma réserve','#reserve/'+r.id)}${btn('Corriger ma note','reserve-open',r.id)}</div></div>`).join('')||empty('Les récoltes et provisions se notent ici.')}</div>${btn('Noter une réserve','add-reserve','',true)}${reserveForm()}`)+
 section('Mes fournées sur l’étagère',lots.length?lots.map(l=>lotSummary(book,l)).join(''):empty('Une fournée se note depuis sa fiche de confiture ou de fruits en bocal.'))+
 section('Les recettes du garde-manger',`<div id="preparation-list">${book.preparations.map(p=>`<div class="row">${art('jar')}<div><h3>${esc(p.name)}</h3><p class="hand">${p.referenceId?'La bassine, les pots et le tour de main':'Ma recette à compléter'}</p>${action('Ouvrir la fiche','#preparation/'+p.id)}</div></div>`).join('')}</div>${btn('Ajouter une fiche de préparation','new-preparation')}`),['basin','funnel','tin']);wireReserveForm();
}
function preparation(p){
 if(!p.referenceId){draftPreparation(p);return;}
 page('LE GARDE-MANGER',procedureBody(p)+section('Mon coup de crayon',`<form id="preparation-notes"><label class="field">Mes notes<textarea name="notes" maxlength="12000">${esc(p.notes)}</textarea></label><button>Garder ma note</button></form>`,'board')+lotForm(p)+section('Les fournées de cette recette',(book.pantryLots??[]).filter(l=>l.preparationId===p.id).map(l=>lotSummary(book,l)).join('')||'<p class="hand">La première étiquette attend son pot.</p>')+section('À la table du chef',recipeLinks(book,p.search))+action('Retour au garde-manger','#garde-manger'),['basin','funnel','tin']);
 document.querySelector('#preparation-notes').onsubmit=async e=>{e.preventDefault();const notes=e.target.elements.notes.value;await change(n=>{n.preparations.find(row=>row.id===p.id).notes=notes;return n;},{text:'Le petit mot est au carnet.'});};
 document.querySelector('#lot-form').onsubmit=async e=>{e.preventDefault();const f=e.target,numeric=name=>f.elements[name].value===''?null:Number(f.elements[name].value),text=name=>f.elements[name].value.trim();await change(n=>addPantryLot(n,{preparationId:p.id,label:text('label'),date:text('date'),jarCount:numeric('jarCount'),netWeightG:numeric('netWeightG'),container:text('container'),closure:text('closure'),equipment:text('equipment'),altitudeM:numeric('altitudeM'),treatmentMinutes:numeric('treatmentMinutes'),ingredientsNotes:text('ingredientsNotes'),treatmentNotes:text('treatmentNotes'),location:text('location'),notes:text('notes')}),{text:'La fournée et ses pots sont notés.'});};
}
function reserveView(r){
 page('LE GARDE-MANGER',reserveBody(book,r)+`<details><summary>Corriger ma réserve ou noter son poids</summary>${reserveForm(r)}</details>`,['jar','basin']);wireReserveForm(r);
 const opening=document.querySelector('#jar-open-form');if(r.pantryLotId&&opening)opening.onsubmit=async e=>{e.preventDefault();await change(n=>openPantryJar(n,r.id,e.target.elements.date.value),{text:'La date d’ouverture est au carnet.'});};
 const use=document.querySelector('#reserve-use-form');if(r.quantity!==null&&use)use.onsubmit=async e=>{e.preventDefault();const f=e.target;await change(n=>useReserve(n,{reserveId:r.id,recipeId:f.elements.recipeId.value||null,quantity:fromMetricQuantity(Number(f.elements.quantity.value),r.unit),date:f.elements.date.value,notes:f.elements.notes.value}),{text:'Prélèvement noté et réserve ajustée.'});};
}
function draftPreparation(p){p=metricPreparation(p);page('LE GARDE-MANGER',heading(p.name,'Brouillon · à documenter')+`<div class="row">${art('jar')}<div><span class="ribbon">Procédé vérifié requis</span><p class="hand">Ajouter la recette et sa source avant préparation.</p></div></div>${section('Ingrédients',`<ul class="ingredients">${p.ingredients.map(i=>`<li><span>${esc(i.name)}</span><span class="amount">${esc(displayQuantity(i.quantity))} ${i.quantity===null?'':esc(i.unit)}</span></li>`).join('')}</ul>`)}${section('Rendement','<p class="hand">À mesurer.</p>','basin')}${section('Méthode et conservation',`<p class="hand">${esc(p.method||'Ajouter une méthode documentée, sans improviser le traitement.')}</p><p class="notice warning">La saisie d’une source ne vérifie pas automatiquement le procédé. Ce brouillon ne constitue pas une consigne de conservation sûre.</p>`,'cocotte')}${section('Stockage',`<p class="hand">${esc(p.storage||'Conditions et durée à documenter.')}</p>`,'tin')}<details><summary>Compléter le brouillon</summary><form id="preparation-form"><label class="field">Titre<input name="name" required maxlength="200" value="${esc(p.name)}"></label><label class="field">Ingrédients — une ligne : nom ; quantité ; unité<textarea name="ingredients" maxlength="12000">${esc(p.ingredients.map(i=>`${i.name} ; ${i.quantity??''} ; ${i.unit}`).join('\n'))}</textarea></label><label class="field">Référence du procédé éprouvé<input name="source" maxlength="1500" value="${esc(p.source)}" placeholder="Source précise, recette et lien"></label><label class="field">Méthode documentée<textarea name="method" maxlength="8000">${esc(p.method)}</textarea></label><label class="field">Stockage documenté<textarea name="storage" maxlength="1500">${esc(p.storage)}</textarea></label><label class="field">Lot<input name="lot" maxlength="100" value="${esc(p.lot)}"></label><label class="field">Mes notes<textarea name="notes" maxlength="12000">${esc(p.notes)}</textarea></label><button class="primary">Enregistrer le brouillon</button></form></details>${section('Les lots conservés',book.reserves.filter(r=>r.lot&&r.lot===p.lot).map(r=>`<p>${esc(r.lot)} · ${esc(r.name)}</p>`).join('')||empty('Dates et suivi à renseigner.'))}${p.source?`<p class="source-link">Source saisie : ${esc(p.source)}</p>`:''}`,['ladle','waffle','madeleine']);document.querySelector('#preparation-form').onsubmit=async e=>{e.preventDefault();const f=e.target;const ingredients=f.elements.ingredients.value.split('\n').filter(s=>s.trim()).map(line=>{const [name,q='',unit='g']=line.split(';').map(s=>s.trim());return {name,quantity:q===''?null:Number(q.replace(',','.')),unit};});const row={...p,name:f.elements.name.value.trim(),ingredients,source:f.elements.source.value.trim(),method:f.elements.method.value,storage:f.elements.storage.value,lot:f.elements.lot.value,notes:f.elements.notes.value,status:'undocumented'};await change(n=>{n.preparations=n.preparations.filter(r=>r.id!==row.id);n.preparations.push(row);return n;},{text:'Brouillon enregistré. Son procédé reste à documenter et à vérifier.'});};}
function preferences(){page('LE CARNET DE PIERRE',heading('Préférences et sauvegardes')+section('Ce qui me convient',`<p class="hand">Un carnet à mon goût.</p><form id="preferences-form"><label class="check"><input name="apple" type="checkbox"${book.settings.apple?' checked':''}><span>Pomme (fruit)<span class="state">Allergie déclarée</span></span></label><label class="check"><input name="oats" type="checkbox"${book.settings.oats?' checked':''}><span>Flocons d’avoine<span class="state">Mauvaise tolérance</span></span></label><p>Pomme de terre <span class="hand">Non exclue</span></p><h2>En cuisine</h2><label class="check"><input name="sound" type="checkbox"${book.settings.sound?' checked':''}><span>Sonnerie du minuteur</span></label><label class="check"><input name="keepAwake" type="checkbox"${book.settings.keepAwake?' checked':''}><span>Garder l’écran allumé</span></label><p class="help">Selon les possibilités du téléphone ; aucune sonnerie en arrière-plan n’est garantie.</p><button>Enregistrer mes préférences</button></form>`,'timer')+section('Conserver mon carnet',`<p class="hand">Je garde une copie de mes recettes.</p><div class="actions">${btn('Exporter mon carnet','export')}${btn('Importer une sauvegarde','show-import')}${btn('Restaurer depuis un fichier','show-import')}</div><label class="field">Fichier de sauvegarde<input id="backup-file" type="file" accept=".json,application/json"></label><div id="import-preview"></div><p class="hand">Dernier export préparé : ${book.lastExportAt?formatDate(book.lastExportAt):'aucun export confirmé'}</p><p class="help">Vérifiez que le fichier a bien été téléchargé. Il contient vos données et photos et n’est pas chiffré.</p>${btn('Exporter le carnet avant remplacement','export-recovery')}`)+section('À propos',`<p class="hand">Le carnet grandit avec vous.</p><p>Carnet personnel · version ${APP_VERSION} · stockage sur cet appareil. Pas de compte ni de synchronisation entre appareils.</p><p class="help">L’effacement des données du navigateur et la navigation privée peuvent faire perdre les données locales. Gardez un export à part. Les recettes et photos restent enregistrées sur cet appareil.</p><p class="help" id="offline-status">${esc(offlineMessage(offlineState))}</p>`)+`<details><summary>Les instruments anciens du carnet</summary><div class="tool-collection">${Object.keys(artwork).filter(key=>['tools-a','tools-b','tools-c'].includes(artwork[key][0])).map(key=>`<figure>${art(key)}<figcaption>${esc(toolName(key))}</figcaption></figure>`).join('')}</div></details>${action('Retour au sommaire','#sommaire')}`,['churn','cakeSlice','nutcracker']);
 document.querySelector('#preferences-form').onsubmit=async e=>{e.preventDefault();const f=e.target,settings={apple:f.elements.apple.checked,oats:f.elements.oats.checked,sound:f.elements.sound.checked,keepAwake:f.elements.keepAwake.checked};if(await change(n=>{n.settings=settings;return n;},{text:'Préférences enregistrées.'}))await updateWakeLock();};wireImport();
}
function toolName(key){return ({basin:'Bassine en cuivre',waffle:'Gaufrier',gravy:'Saucière',pepper:'Moulin à poivre',grater:'Râpe',mandoline:'Mandoline',citrus:'Presse-agrumes',nutcracker:'Casse-noix',knife:'Couteau',grinder:'Moulin à café',kettle:'Bouilloire émaillée',copper:'Casserole en cuivre',mortar:'Mortier',masher:'Presse-purée',mincer:'Hachoir',sieve:'Tamis',mold:'Moule à gâteau',skimmer:'Écumoire',churn:'Baratte',ladle:'Louche',madeleine:'Moule à madeleines',board:'Planche en bois',cakeSlice:'Pelle à gâteau',funnel:'Entonnoir',basket:'Panier métallique',tin:'Boîte émaillée',bottle:'Bouteille à bouchon mécanique'})[key];}
function download(text,filename){const link=document.createElement('a'),u=URL.createObjectURL(new Blob([text],{type:'application/json'}));link.href=u;link.download=filename;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(u),30000);}
async function exportCurrent(key='current'){if(busy)return;setBusy(true);try{const current=await store.read(key);if(!current)throw new Error('Aucune copie avant remplacement n’existe encore.');download(await makeBackup(current),`mon-carnet-${key==='current'?'':'avant-remplacement-'}${dayString()}.json`);setBusy(false);if(key==='current'){await change(n=>{n.lastExportAt=new Date().toISOString();return n;},{text:'Export préparé. Vérifiez sa présence dans vos téléchargements.'});}else notice('Copie précédente préparée ; vérifiez le fichier téléchargé.');}catch(error){setBusy(false);report(error);}}
function wireImport(){document.querySelector('#backup-file').onchange=async e=>{const file=e.target.files[0];stagedBackup=null;const holder=document.querySelector('#import-preview');holder.innerHTML='';if(!file)return;setBusy(true);try{if(file.size>LIMITS.backupBytes)throw new Error('La sauvegarde dépasse 45 Mo.');const parsed=await readBackup(await file.text());await verifyPhotoDecoding(parsed.notebook.photos);stagedBackup=parsed;const n=parsed.notebook;holder.innerHTML=`<div class="notice"><strong>Fichier vérifié</strong><p>${n.recipes.length} recettes, ${n.photos.length} photos, ${n.menus.length} repas, ${n.plants.length} plantes, ${n.reserves.length} réserves.</p><p>${formatDate(parsed.exportedAt)}</p></div><p class="help">Fusionner ajoute les nouvelles données ; les conflits annulent la fusion. Remplacer restaure toutes les données et garde une copie du carnet précédent.</p><label class="check"><input id="replace-confirm" type="checkbox"><span>Je confirme le remplacement de mon carnet.</span></label><div class="actions">${btn('Fusionner les carnets','import-merge')}${btn('Remplacer mon carnet','import-replace')}</div>${btn('Annuler cet import','import-cancel')}`;}catch(error){report(error);}finally{setBusy(false);}};}
async function applyImport(replace){if(!stagedBackup||busy)return;if(replace&&!document.querySelector('#replace-confirm')?.checked){notice('Confirmez le remplacement, ou choisissez Fusionner.',true);return;}setBusy(true);try{const incoming=stagedBackup.notebook,next=replace?incoming:await prepareMerge(book,incoming);book=await store.commit(next,book.revision,{recovery:replace});stagedBackup=null;setBusy(false);render();notice(replace?'Carnet restauré ; le précédent reste exportable.':'Fusion enregistrée sans écrasement silencieux.');}catch(error){setBusy(false);report(error);}}
async function soundReady(){try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();await audioContext.resume();}catch{notice('Ce navigateur ne permet pas la sonnerie. Le minuteur visuel reste disponible.');}}
function beep(){if(!book.settings.sound||!audioContext||audioContext.state!=='running')return;for(let i=0;i<3;i++){const osc=audioContext.createOscillator(),gain=audioContext.createGain(),t=audioContext.currentTime+i*.4;osc.frequency.value=880;gain.gain.setValueAtTime(.15,t);gain.gain.exponentialRampToValueAtTime(.001,t+.25);osc.connect(gain).connect(audioContext.destination);osc.start(t);osc.stop(t+.25);}}
async function updateWakeLock(){if(!book?.settings.keepAwake||!location.hash.startsWith('#cuisine')||document.visibilityState!=='visible'){await wakeLock?.release().catch(()=>{});wakeLock=null;return;}if(wakeLock&&!wakeLock.released)return;const status=document.querySelector('#awake-status');if(!navigator.wakeLock?.request){if(status)status.textContent='Maintien de l’écran non disponible dans ce navigateur.';return;}try{wakeLock=await navigator.wakeLock.request('screen');if(status)status.textContent='Écran maintenu allumé tant que cette page reste visible.';}catch{if(status)status.textContent='Le téléphone a refusé le maintien de l’écran allumé.';}}
function tick(){const t=book?.cooking?.timer;if(!t)return;const left=remaining(t);updateTimerDial(t);const output=document.querySelector('#timer-output'),label=document.querySelector('#timer-label');if(output)output.textContent=clock(left);if(label)label.textContent=left===0?'Temps écoulé':`Il reste ${clock(left)}`;const key=t.endAt;if(t.running&&left===0&&expiredKey!==key){expiredKey=key;beep();notice('Minuteur terminé. Vérifiez votre préparation.');}}
function render(){
 if(!book)return;const previousUrls=urls;urls=[];setTimeout(()=>previousUrls.forEach(URL.revokeObjectURL),1100);clearNotice();stagedBackup=null;dirty=false;draft=null;photoFile=undefined;removePhoto=false;
 const route=location.hash||'#accueil',[name,key]=route.slice(1).split('/');
 const turn=capturePageTurn(main,lastRoute,route),routeChanged=lastRoute!==route;lastRoute=route;
 const recipe=book.recipes.find(r=>r.id===key);
 try{
 if(name==='accueil')home();else if(name==='sommaire'||name==='carnet')index();else if(name==='recettes')recipeList();else if(name==='recette'&&recipe)detail(recipe);else if(name==='repas'){const meal=book.menus.find(m=>m.id===key);if(meal)detail(meal.snapshot,meal);else page('MES MENUS',heading('Ce repas n’est plus au menu')+action('Retour aux menus','#menus'));}else if(name==='modifier'&&recipe)editor(recipe);else if(name==='nouvelle')editor();else if(name==='cuisine')kitchen();else if(name==='marche')market();else if(name==='produit')product(products.find(p=>p.id===key)||products[0]);else if(name==='jardin')garden();else if(name==='culture')gardenGuide(key);else if(name==='plante'&&book.plants.some(p=>p.id===key))plant(book.plants.find(p=>p.id===key));else if(name==='menus')menus();else if(name==='courses')courses();else if(name==='garde-manger')pantry();else if(name==='reserve'&&book.reserves.some(r=>r.id===key))reserveView(book.reserves.find(r=>r.id===key));else if(name==='preparation'&&book.preparations.some(p=>p.id===key))preparation(book.preparations.find(p=>p.id===key));else if(name==='preferences'||name==='sauvegardes')preferences();else{home();notice('Cette page n’est pas disponible dans ce carnet.',true);}
 document.title='Mon carnet de recettes · '+APP_VERSION;updateWakeLock();
 if(routeChanged&&typeof window.scrollTo==='function')window.scrollTo({top:0,behavior:'instant'});
 playPageTurn(turn);
 }catch(error){page('LE CARNET DE PIERRE',heading('La page ne peut pas s’ouvrir')+action('Retour au sommaire','#sommaire'));report(error);}
}
main.addEventListener('input',e=>{if(e.target.closest('form'))dirty=true;});
main.addEventListener('click',async event=>{
 const b=event.target.closest('[data-action]');if(!b||busy)return;const a=b.dataset.action,v=b.dataset.value;
 try{
 if(a==='bookmark')await change(n=>{n.bookmarkedId=n.bookmarkedId===v?null:v;return n;},{text:'Marque-page enregistré.'});
 else if(a==='favorite')await change(n=>{n.favoriteIds=n.favoriteIds.includes(v)?n.favoriteIds.filter(x=>x!==v):[...n.favoriteIds,v];return n;},{text:'Favoris enregistrés.'});
 else if(a.startsWith('servings-')){const r=book.recipes.find(r=>r.id===v),target=servingsById.get(v)??r.servings;servingsById.set(v,Math.min(100,Math.max(1,target+(a==='servings-plus'?1:-1))));detail(r);}
 else if(a==='cook'||a==='cook-meal'){const meal=a==='cook-meal'?book.menus.find(m=>m.id===v):null;const r=a==='cook-meal'?meal?.snapshot:book.recipes.find(r=>r.id===v);if(!r)throw Error('Ce repas ou cette recette est introuvable.');if(book.cooking&&!confirm('Une préparation est déjà en cours. La remplacer par cette recette ?'))return;if(await change(n=>beginCooking(n,r,meal?.servings??servingsById.get(v)??r.servings,{menuId:meal?.id}),{redraw:false,text:''}))navigate('#cuisine');}
 else if(a==='timer-toggle'){await soundReady();await change(n=>{n.cooking.timer=timerAction(n.cooking.timer,n.cooking.timer.running?'pause':'start');return n;},{text:'Minuteur enregistré.'});}
 else if(a==='timer-reset')await change(n=>{n.cooking.timer=timerAction(n.cooking.timer,'reset');return n;});
 else if(a==='show-timer'){document.querySelector('#timer-form').hidden=false;document.querySelector('#timer-form input').focus();}
 else if(a==='previous-step')await change(n=>{n.cooking.stepIndex=Math.max(0,n.cooking.stepIndex-1);return n;},{text:'Étape enregistrée.'});
 else if(a==='next-step')await change(n=>{const c=n.cooking;c.completed=[...new Set([...c.completed,c.stepIndex])];if(c.stepIndex<c.snapshot.steps.length-1)c.stepIndex++;else n.cooking=null;return n;},{text:'Progression de cuisine enregistrée.'});
 else if(a==='category'){category=category===v?'':v;recipeList();}
 else if(a==='product-recipes'){searchQuery=v;category='';navigate('#recettes');}
 else if(a==='plant-recipes'){searchQuery=v==='fraisier'?'fraise':v;category='';navigate('#recettes');}
 else if(a==='space'){plantSpace=v;garden();}
 else if(a==='add-plant'||a==='edit-plant'){document.querySelector('#plant-form').hidden=false;document.querySelector('#plant-form input').focus();}
 else if(a==='discard-jar')await change(n=>{const r=n.reserves.find(r=>r.id===v);if(!r?.pantryLotId)throw Error('Ce pot est introuvable.');r.discarded=true;return n;},{text:'Pot mis à l’écart ; son historique reste au carnet.'});
 else if(a==='undo-reserve-use')await change(n=>undoReserveUse(n,v),{text:'Prélèvement annulé. La date d’ouverture reste notée.'});
 else if(a==='harvest-reserve')await change(n=>harvestToReserve(n,v),{text:'Récolte ajoutée une seule fois aux réserves.'});
 else if(a==='week-prev'||a==='week-next'){week=shiftDay(week,a==='week-prev'?-7:7);menus();}
 else if(a==='menu-choose')menuEditor(v);
 else if(a==='cancel-menu'){document.querySelector('#menu-editor').hidden=true;dirty=false;}
 else if(a==='menu-remove')await change(n=>{n.menus=n.menus.filter(m=>m.id!==v);return n;},{text:'Repas retiré. Actualisez les courses pour recalculer la liste.'});
 else if(a==='generate-courses'||a==='refresh-courses'){const selected=a==='refresh-courses'?(book.shopping.week??week):week;if(await change(n=>rebuildShopping(n,selected),{redraw:false,text:''})){navigate('#courses');setTimeout(()=>notice('Courses recalculées ; articles personnels conservés.'),0);}}
 else if(a==='at-home'){const [key,rowId]=v.split('|');await change(n=>{const r=n.shopping[key].find(r=>r.id===rowId);r.atHome=!r.atHome;return n;},{text:'Disponibilité de l’article enregistrée.'});}
 else if(a==='copy-courses'){const text=[...book.shopping.generated,...book.shopping.personal].map(r=>`${r.bought?'☑':'☐'} ${r.name} — ${displayQuantity(r.quantity)} ${r.quantity===null?'':r.unit}${r.atHome?' (déjà à la maison)':''}`).join('\n');try{await navigator.clipboard.writeText(text);notice('Liste copiée.');}catch{const area=document.createElement('textarea');area.value=text;area.setAttribute('aria-label','Liste à copier');main.querySelector('.page-body').append(area);area.focus();area.select();notice('Copie automatique indisponible. Le texte est sélectionné pour une copie manuelle.');}}
 else if(a==='add-reserve'){document.querySelector('#reserve-form').hidden=false;document.querySelector('#reserve-form input').focus();}
 else if(a==='reserve-open'){const r=book.reserves.find(r=>r.id===v);const f=document.querySelector('#reserve-form');f.outerHTML=reserveForm(r);wireReserveForm(r);document.querySelector('#reserve-form').scrollIntoView({block:'nearest'});}
 else if(a==='scroll-reserves'||a==='scroll-preparations')document.querySelector(a==='scroll-reserves'?'#reserve-list':'#preparation-list').scrollIntoView({block:'start'});
 else if(a==='new-preparation'){const p={id:id(),name:'Ma préparation à documenter',status:'undocumented',ingredients:[],source:'',method:'',storage:'',lot:'',notes:''};if(await change(n=>{n.preparations.push(p);return n;},{redraw:false,text:''}))navigate('#preparation/'+p.id);}
 else if(a==='export')await exportCurrent();else if(a==='export-recovery')await exportCurrent('before-import');
 else if(a==='show-import')document.querySelector('#backup-file').click();
 else if(a==='import-merge'||a==='import-replace')await applyImport(a==='import-replace');
 else if(a==='import-cancel'){stagedBackup=null;document.querySelector('#backup-file').value='';document.querySelector('#import-preview').innerHTML='';notice('Import annulé ; carnet inchangé.');}
 }catch(error){report(error);}
});
document.addEventListener('click',event=>{const link=event.target.closest('a[href^="#"]');if(!link)return;if(link.classList.contains('skip')){event.preventDefault();main.focus();return;}if(busy){event.preventDefault();notice('Patientez jusqu’à la fin de l’enregistrement.');return;}if(dirty&&!confirm('Des modifications ne sont pas enregistrées. Quitter cette page ?'))event.preventDefault();else dirty=false;});
let reverting=false;window.addEventListener('hashchange',()=>{if(reverting){reverting=false;return;}if(busy||dirty&&!confirm('Des modifications ne sont pas enregistrées. Quitter cette page ?')){reverting=true;location.hash=lastRoute;return;}render();});
window.addEventListener('beforeunload',e=>{if(dirty||busy){e.preventDefault();e.returnValue='';}});document.addEventListener('visibilitychange',()=>{tick();updateWakeLock();});setInterval(tick,500);
try{book=await store.read();let integrationError;try{const recipes=installCatalogue(book),additional=installAdditionalCatalogues(recipes.notebook),garden=installGardenPantry(additional.notebook),metric=installMetricPantry(garden.notebook);if(recipes.changed||additional.changed||garden.changed||metric.changed)book=await store.commit(metric.notebook,book.revision);}catch(error){integrationError=error;}render();if(integrationError)report(integrationError);}catch(error){page('LE CARNET DE PIERRE',heading('Le carnet ne peut pas s’ouvrir')+'<p>Vos données ne sont pas effacées. Réessayez dans votre navigateur habituel.</p><button onclick="location.reload()">Réessayer</button>');report(error);}

startOffline(showOffline);
